export const HI3D_GENERATED_FILE_PREFIX = 'hi3d-';

/** Normalize the old Hi3D_/Hi3D. spellings before applying the workspace naming contract. */
export function stripHi3dGeneratedFilePrefix(value: string): string {
  const match = /^hi3d[-_.\s]+(.+)$/i.exec(value);
  return match?.[1] ?? value;
}

export function hi3dGeneratedFileName(value: string, fallback = 'artifact'): string {
  const remainder = stripHi3dGeneratedFilePrefix(value).trim() || fallback;
  return `${HI3D_GENERATED_FILE_PREFIX}${remainder}`;
}

export function hasHi3dGeneratedFilePrefix(value: string): boolean {
  return value.startsWith(HI3D_GENERATED_FILE_PREFIX);
}

/** 模型版本文件名约定：`<模型名>_<序号>.glb`，序号最大的是最新版。Runtime 与 runtime-mock 共用。 */
export const MODEL_FILE_NAME_RE = /^(.+)_(\d+)\.glb$/i;

export interface ParsedModelFileName {
  /** 已去掉 `hi3d-` 前缀的模型名 */
  name: string;
  index: number;
}

/** 解析模型版本文件名；不符合约定返回 null。 */
export function parseModelFileName(fileName: string): ParsedModelFileName | null {
  const match = MODEL_FILE_NAME_RE.exec(fileName);
  if (!match) return null;
  return { name: stripHi3dGeneratedFilePrefix(match[1]!), index: Number(match[2]) };
}
